fn check_match_at(main: &Vec<i32>, sub: &Vec<i32>, start: usize) -> bool {
    // Precondition (as stated in the problem): start + sub.len() <= main.len()
    // If callers violate it, we safely return false.
    if start > main.len() || sub.len() > main.len() - start {
        return false;
    }

    for j in 0..sub.len() {
        if main[start + j] != sub[j] {
            return false;
        }
    }
    true
}

fn is_sub_array(main: &Vec<i32>, sub: &Vec<i32>) -> bool {
    // Empty sub array always matches.
    if sub.is_empty() {
        return true;
    }
    // If sub is longer than main, it cannot match.
    if sub.len() > main.len() {
        return false;
    }

    let last_start = main.len() - sub.len();
    for start in 0..=last_start {
        if check_match_at(main, sub, start) {
            return true;
        }
    }
    false
}